// src/tools/compass-profile-workspace.ts
init_errors();

// src/workspace-profiler.ts
function generateWorkspaceDescription(files) {
  const parts = [];
  const sortedFiles = [...files].sort((a, b) => a.path.localeCompare(b.path));
  for (const file3 of sortedFiles) {
    if (file3.path.endsWith("package.json")) {
      try {
        const pkg = JSON.parse(file3.content);
        if (pkg.name)
          parts.push(`Project: ${pkg.name}`);
        if (pkg.dependencies) {
          parts.push(`Dependencies: ${Object.keys(pkg.dependencies).sort().join(", ")}`);
        }
        if (pkg.devDependencies) {
          parts.push(`Dev dependencies: ${Object.keys(pkg.devDependencies).sort().join(", ")}`);
        }
        if (pkg.scripts) {
          parts.push(`Scripts: ${Object.keys(pkg.scripts).sort().join(", ")}`);
        }
      } catch {}
    } else if (file3.path.endsWith("tsconfig.json")) {
      parts.push("TypeScript project");
    } else if (file3.path.endsWith("biome.json")) {
      parts.push("Uses Biome for linting/formatting");
    } else if (file3.path.endsWith(".eslintrc") || file3.path.endsWith(".eslintrc.json")) {
      parts.push("Uses ESLint");
    } else if (file3.path.endsWith("README.md")) {
      const firstPara = file3.content.split(`

`)[0]?.replace(/^#.*\n/, "").trim();
      if (firstPara)
        parts.push(`Description: ${firstPara.slice(0, 200)}`);
    }
    const ext = file3.path.split(".").pop();
    if (ext === "ts" || ext === "tsx")
      parts.push("TypeScript");
    else if (ext === "py")
      parts.push("Python");
    else if (ext === "rs")
      parts.push("Rust");
    else if (ext === "go")
      parts.push("Go");
  }
  return [...new Set(parts)].join(". ");
}
function generateMatchReason(workspaceDescription, artifactKeywords, artifactDescription) {
  const descLower = workspaceDescription.toLowerCase();
  const matchingKeywords = artifactKeywords.filter((kw) => descLower.includes(kw.toLowerCase()));
  if (matchingKeywords.length > 0) {
    return `Matches workspace: ${matchingKeywords.join(", ")}`;
  }
  const artifactWords = artifactDescription.toLowerCase().split(/\s+/);
  const descWords = new Set(descLower.split(/\s+/));
  const overlap = artifactWords.filter((w) => w.length > 3 && descWords.has(w));
  if (overlap.length > 0) {
    return `Related to: ${[...new Set(overlap)].slice(0, 5).join(", ")}`;
  }
  return "Semantically similar to workspace profile";
}

// src/tools/compass-profile-workspace.ts
async function handleCompassProfileWorkspace(input, ctx) {
  if (!input.files || input.files.length === 0) {
    return jsonResult6({
      results: [],
      message: "No files provided. Include key workspace files like package.json, tsconfig.json, README.md for best results."
    });
  }
  try {
    const description = generateWorkspaceDescription(input.files);
    const embedding = await ctx.embeddingProvider.embed(description);
    const topK = input.topK ?? 10;
    const minScore = input.minScore ?? 0.4;
    const response = await ctx.solrClient.searchByThreshold(embedding, topK, minScore);
    const results = response.response.docs.map((doc3) => {
      try {
        const parsed = fromSolrDocument(doc3);
        const keywords = typeof doc3.keywords === "string" ? doc3.keywords.split(",") : [];
        const matchReason = generateMatchReason(description, keywords, parsed.description ?? "");
        return {
          artifactName: parsed.artifactName,
          displayName: parsed.displayName,
          type: parsed.type,
          relevanceScore: parsed.score,
          description: parsed.description,
          matchReason
        };
      } catch {
        return null;
      }
    }).filter((r) => r !== null);
    if (input.persist) {
      try {
        const memDoc = toMemoryDocument(description, embedding, "workspace_profile", undefined, undefined, modelIdentity(ctx.embeddingProvider));
        const meta5 = {};
        for (const [key, value] of Object.entries(memDoc)) {
          if (key !== "id" && key !== "text" && key !== "vector" && value != null) {
            meta5[key] = String(value);
          }
        }
        await ctx.userSolrClient.upsert(memDoc.id, memDoc.text, memDoc.vector, meta5);
      } catch {}
    }
    return jsonResult6({
      workspaceDescription: description,
      resultCount: results.length,
      results
    });
  } catch (err) {
    if (err instanceof SoukCompassError && err.code === ErrorCodes.SOLR_CONNECTION) {
      return jsonResult6({
        results: [],
        error: `Solr is unreachable. ${err.message}`
      });
    }
    throw err;
  }
}
