async function handleCompassReindex(input, ctx) {
  try {
    const force = input.force ?? false;
    const catalog = await loadCatalog(ctx.contentRoot);
    const existingDocs = await fetchExistingArtifactDocs(ctx);
    const solrMap = new Map;
    for (const doc3 of existingDocs) {
      const id = doc3.id;
      solrMap.set(id, {
        version: typeof doc3.version === "string" ? doc3.version : undefined,
        contentHash: typeof doc3.content_hash === "string" ? doc3.content_hash : undefined
      });
    }
    let added = 0;
    let updated = 0;
    let unchanged = 0;
    const toIndex = [];
    for (const entry of catalog) {
      const solrDoc = solrMap.get(entry.name);
      if (!solrDoc) {
        added++;
        toIndex.push({ entry, reason: "added" });
        continue;
      }
      if (force) {
        updated++;
        toIndex.push({ entry, reason: "forced" });
        solrMap.delete(entry.name);
        continue;
      }
      if (solrDoc.version !== entry.version) {
        updated++;
        toIndex.push({ entry, reason: "version_changed" });
        solrMap.delete(entry.name);
        continue;
      }
      const { body } = await readArtifactContent(ctx.contentRoot, entry);
      const embeddingText = buildEmbeddingText(entry.displayName, entry.description, body);
      const hash3 = contentHash(embeddingText);
      if (solrDoc.contentHash !== hash3) {
        updated++;
        toIndex.push({ entry, reason: "content_changed" });
        solrMap.delete(entry.name);
        continue;
      }
      unchanged++;
      solrMap.delete(entry.name);
    }
    const removedIds = [...solrMap.keys()];
    const removed = removedIds.length;
    for (const id of removedIds) {
      try {
        await ctx.solrClient.delete(id);
      } catch {}
    }
    for (const { entry } of toIndex) {
      const { body } = await readArtifactContent(ctx.contentRoot, entry);
      const embeddingText = buildEmbeddingText(entry.displayName, entry.description, body);
      const embedding = await ctx.embeddingProvider.embed(embeddingText);
      const doc3 = toSolrDocument(entry, embeddingText, embedding, modelIdentity(ctx.embeddingProvider));
      await ctx.solrClient.upsert(doc3.id, doc3.text, doc3.vector, extractMetadata3(doc3), { commit: false });
    }
    if (toIndex.length > 0 || removedIds.length > 0) {
      await ctx.solrClient.commit();
    }
    return jsonResult9({ added, updated, unchanged, removed });
  } catch (err) {
    if (err instanceof SoukCompassError && err.code === ErrorCodes.SOLR_CONNECTION) {
      return jsonResult9({
        added: 0,
        updated: 0,
        unchanged: 0,
        removed: 0,
        error: `Solr is unreachable. Ensure Solr is running at the configured URL. ${err.message}`
      });
    }
    throw err;
  }
}
async function fetchExistingArtifactDocs(ctx) {
  const params = new URLSearchParams({
    q: 'doc_source:"artifact" AND -id:*__chunk_*',
    fl: "id,version,content_hash",
    rows: "10000",
    wt: "json"
  });
  const url3 = `${ctx.config.solrUrl}/solr/${encodeURIComponent(ctx.config.solrCollection)}/select?${params.toString()}`;
  const response = await fetch(url3);
  if (!response.ok) {
    throw new SoukCompassError(`Failed to query existing artifacts: HTTP ${response.status}`, ErrorCodes.SOLR_HTTP, { httpStatus: response.status });
  }
  const body = await response.json();
  return body.response?.docs ?? [];
}
function extractMetadata3(doc3) {
  const meta5 = {};
  const metadataKeys = [
    "artifact_name",
    "artifact_type",
    "display_name",
    "maturity",
    "collection_names",
    "keywords",
    "author",
    "version",
    "doc_source",
    "content_hash"
  ];
  for (const key of metadataKeys) {
    if (doc3[key] != null) {
      const val = doc3[key];
      if (Array.isArray(val)) {
        meta5[key] = val.map(String);
      } else {
        meta5[key] = String(val);
      }
    }
  }
  return meta5;
}
function jsonResult9(data) {
  return {
    content: [{ type: "text", text: JSON.stringify(data, null, 2) }]
  };
}

