// src/tools/compass-status.ts
async function handleCompassStatus(_input, ctx) {
  const configuredProvider = modelIdentity(ctx.embeddingProvider);
  const targets = collectionTargets(ctx.tenants.tenants, [
    "artifacts",
    "memory",
    "codebase"
  ]);
  const collections = [];
  for (const target of targets) {
    const owner = ctx.tenants.tenants.find((t) => target.tenantIds.includes(t.id));
    collections.push({
      name: target.collection,
      solrUrl: target.solrUrl,
      partition: target.partition,
      tenants: target.tenantIds,
      replicationFactor: target.durability.replicationFactor,
      ...owner ? { backupRepository: owner.backup.repository } : {},
      ...await collectionFacets(target.solrUrl, target.collection)
    });
  }
  const memoryNotes = await countMemoryNotes(ctx);
  for (const solrUrl of new Set(collections.map((c) => c.solrUrl))) {
    const cluster = await getClusterReplicaHealth(solrUrl);
    for (const collection of collections) {
      if (collection.solrUrl !== solrUrl)
        continue;
      const replicas = cluster.get(collection.name);
      if (replicas)
        collection.minActiveReplicas = replicas.minActiveReplicas;
    }
  }
  const totalDocs = collections.reduce((s, c) => s + (c.docCount ?? 0), 0);
  const staleCollections = collections.filter((c) => (c.untaggedDocs ?? 0) > 0 || Object.keys(c.embedProviders ?? {}).some((p) => p !== configuredProvider)).map((c) => c.name);
  const underReplicated = collections.filter((c) => c.minActiveReplicas != null && c.replicationFactor != null && c.minActiveReplicas < c.replicationFactor).map((c) => ({
    collection: c.name,
    requested: c.replicationFactor,
    active: c.minActiveReplicas
  }));
  const unmigrated = collections.filter((c) => (c.untenantedDocs ?? 0) > 0 || Object.keys(c.schemaVersions ?? {}).some((v) => Number(v) < MEMORY_SCHEMA_VERSION)).map((c) => c.name);
  const cacheStats = "getStats" in ctx.embeddingProvider ? ctx.embeddingProvider.getStats() : null;
  const result = {
    tenants: ctx.tenants.tenants.map((t) => ({
      id: t.id,
      scope: t.scope,
      access: t.access,
      precedence: t.precedence
    })),
    defaultTenant: ctx.tenants.defaultTenantId,
    collections,
    totalDocs,
    memoryNotes,
    embedProvider: configuredProvider,
    embedDimensions: ctx.embeddingProvider.dimensions,
    schemaVersion: MEMORY_SCHEMA_VERSION
  };
  if (staleCollections.length > 0) {
    result.providerMismatch = {
      configured: configuredProvider,
      collections: staleCollections,
      warning: "These collections hold vectors this provider did not produce. " + "Similarity against them is not meaningful \u2014 reindex them."
    };
  }
  if (underReplicated.length > 0) {
    result.underReplicated = {
      collections: underReplicated,
      warning: "Fewer replicas are active than were requested at creation. These " + "collections are answering queries correctly and are one node " + "failure from not existing."
    };
  }
  if (unmigrated.length > 0) {
    result.unmigratedCollections = {
      collections: unmigrated,
      currentVersion: MEMORY_SCHEMA_VERSION,
      warning: "These collections hold documents written before the current data " + "model. They are read through the legacy fallback \u2014 attributed to " + "the personal tenant, treated as active and open-ended \u2014 which is " + "correct but coarse."
    };
  }
  if (cacheStats) {
    result.cache = cacheStats;
  }
  return {
    content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
  };
}
async function countMemoryNotes(ctx) {
  const counts = {};
  for (const tenant of ctx.tenants.tenants) {
    try {
      const url3 = `${tenant.solrUrl}/solr/${encodeURIComponent(tenant.collections.memory)}/select` + `?q=doc_source:%22memory%22&rows=0&wt=json` + `&fq=${encodeURIComponent(`tenant_id:"${tenant.id}"`)}`;
      const response = await fetch(url3);
      if (!response.ok) {
        counts[tenant.id] = null;
        continue;
      }
      const body = await response.json();
      counts[tenant.id] = body.response?.numFound ?? 0;
    } catch {
      counts[tenant.id] = null;
    }
  }
  return counts;
}

// src/tools/compass-tenants.ts
async function handleCompassTenants(input, ctx) {
  const verify2 = input.verify ?? false;
  const tenants = await Promise.all(ctx.tenants.tenants.map(async (tenant) => {
    const base = {
      id: tenant.id,
      scope: tenant.scope,
      displayName: tenant.displayName,
      access: tenant.access,
      precedence: tenant.precedence,
      isDefault: tenant.id === ctx.tenants.defaultTenantId,
      solrUrl: tenant.solrUrl,
      collections: tenant.collections,
      durability: tenant.durability
    };
    if (!verify2)
      return base;
    const partitions = Object.entries(tenant.collections);
    const health = await Promise.all(partitions.map(async ([partition, collection]) => {
      const info = await getCollectionInfo(tenant.solrUrl, collection);
      const replicas = info.exists ? await getReplicaHealth(tenant.solrUrl, collection) : null;
      return {
        partition,
        collection,
        exists: info.exists,
        docCount: info.docCount,
        ...replicas ? {
          shards: replicas.shards.length,
          minActiveReplicas: replicas.minActiveReplicas,
          redundant: (replicas.minActiveReplicas ?? 0) > 1
        } : {}
      };
    }));
    return { ...base, health };
  }));
  const shared = collectionTargets(ctx.tenants.tenants, [
    "artifacts",
    "memory",
    "codebase"
  ]).filter((target) => target.tenantIds.length > 1).map((target) => ({
    collection: target.collection,
    solrUrl: target.solrUrl,
    tenants: target.tenantIds
  }));
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify({
          defaultTenant: ctx.tenants.defaultTenantId,
          collectionPrefix: ctx.tenants.collectionPrefix,
          registrySource: ctx.tenants.sourcePath ?? "none (personal only)",
          registryPath: ctx.config.tenantRegistryPath ?? defaultTenantRegistryPath(),
          tenants,
          ...shared.length > 0 ? {
            sharedCollections: shared,
            sharedCollectionsNote: "These collections hold more than one tenant's records, separated only by the tenant_id filter rather than by Solr-level isolation."
          } : {}
        }, null, 2)
      }
    ]
  };
}

